begin;
create temporary table service_notes_import as select * from jsonb_to_recordset($notes$[{"name": "Clasico Ceviche", "source_page": 1, "table_setting": "One sharing spoon on a plate and a spoon for each guest.", "observations": "Classic ceviche."}, {"name": "Wasabi Ceviche", "source_page": 1, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "Kiiro Ceviche", "source_page": 2, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "OSK Ceviche", "source_page": 2, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "Kare Ceviche", "source_page": 3, "table_setting": "Ceviche spoon per guest and a sharing spoon per table.", "observations": "No allowance to change the lobster. Sauce is poured once the dish is dropped on the table."}, {"name": "Moriawase Ceviche", "source_page": 3, "table_setting": "One sharing spoon on a plate and a spoon for each guest.", "observations": null}, {"name": "Akami Truffle", "source_page": 4, "table_setting": "Place in the center of the table.", "observations": "Recommend enjoying immediately, before the crackers get wet."}, {"name": "Otoro & Cecina Tiradito", "source_page": 4, "table_setting": "A small spoon per guest, chopsticks, and share plates.", "observations": "Regular presentation."}, {"name": "Hotate Nissei", "source_page": 5, "table_setting": "One smaller spoon for each guest.", "observations": "Send sepia crackers only if guests specifically request them."}, {"name": "Peru", "source_page": 5, "table_setting": "One smaller spoon for each guest.", "observations": "Camote is not fried with shellfish."}, {"name": "Carpassion", "source_page": 6, "table_setting": "One smaller spoon for each guest.", "observations": "Recommend spreading the phyllo strips for crunch in every bite."}, {"name": "Inca", "source_page": 7, "table_setting": "Center of the table to share.", "observations": "Recommend not using soy sauce."}, {"name": "Hamachi Brasa", "source_page": 7, "table_setting": null, "observations": "Recommend not using soy sauce."}, {"name": "Katsu", "source_page": 8, "table_setting": "Center of the table to share.", "observations": "Recommend not using soy sauce."}, {"name": "Hotate Truffle", "source_page": 8, "table_setting": "Center of the table to share.", "observations": "Recommend not using soy sauce. Torched at the table."}, {"name": "Ebi / Lobster Mentaiko", "source_page": 9, "table_setting": "Center of the table to share.", "observations": "Torched at the table."}, {"name": "Tuna Foie", "source_page": 9, "table_setting": "Center of the table to share.", "observations": "Recommend not using soy sauce. Torched at the table."}, {"name": "Miso Lobster", "source_page": 10, "table_setting": null, "observations": "Recommend not using soy sauce. Torched at the table."}, {"name": "Pisco Buta", "source_page": 10, "table_setting": "Place in the center of the table.", "observations": "Recommend not using soy sauce. Torched at the table."}, {"name": "Veggie Brasa", "source_page": 11, "table_setting": "Place in the center of the table.", "observations": "Brushed with tamari, but the Brasa Sauce contains regular soy sauce."}, {"name": "Niku", "source_page": 11, "table_setting": "Place in the center of the table. Torch.", "observations": "Recommend not using soy sauce. Torched at the table."}, {"name": "Cecina Nigiri", "source_page": 12, "table_setting": null, "observations": null}, {"name": "Kani TNT", "source_page": 13, "table_setting": null, "observations": null}, {"name": "Veggie Truffle", "source_page": 13, "table_setting": "Truffle ponzu sauce on the side.", "observations": null}, {"name": "Tuna Tartare", "source_page": 14, "table_setting": null, "observations": null}, {"name": "Nori Furai", "source_page": 14, "table_setting": null, "observations": null}, {"name": "Nikkei", "source_page": 15, "table_setting": null, "observations": null}, {"name": "Antiku", "source_page": 15, "table_setting": null, "observations": null}, {"name": "Rocoto Aburi", "source_page": 16, "table_setting": null, "observations": null}, {"name": "Nikkei Salad", "source_page": 17, "table_setting": "Two spoons in the center to serve; silverware if requested.", "observations": null}, {"name": "Crispy Rice", "source_page": 17, "table_setting": "No utensils; set in the center of the table.", "observations": null}, {"name": "Temaki OSK", "source_page": 18, "table_setting": null, "observations": "A few drops of shoyu when it arrives at the table."}, {"name": "Kani Taco", "source_page": 18, "table_setting": "Place in the center of the table.", "observations": null}, {"name": "Toro Tartare", "source_page": 19, "table_setting": "Two spoons in the center of the table to mix and serve.", "observations": "Pour soy sauce in the center and explain the dish. Ask guests if they would like assistance mixing it."}, {"name": "Niku Tartare", "source_page": 19, "table_setting": "Two spoons in the center of the table to mix and serve.", "observations": "Prepared tableside. Present to the table and ask if they want you to mix it."}, {"name": "Ponzu Veggies", "source_page": 20, "table_setting": "Set in the center of the table, with silverware if requested.", "observations": null}, {"name": "Tumbo Shrimp", "source_page": 20, "table_setting": "Place in the center of the table.", "observations": null}, {"name": "Mariscos al Fuego", "source_page": 21, "table_setting": null, "observations": null}, {"name": "Tako Anticucho", "source_page": 21, "table_setting": "Served on hot stones.", "observations": null}, {"name": "Pisco Ribs", "source_page": 22, "table_setting": "Silverware and oshiboris for cleaning hands.", "observations": null}, {"name": "Niku Gyoza", "source_page": 22, "table_setting": "Silverware.", "observations": "Changes are not available."}, {"name": "Sea Bass Misoy