 and one smaller spoon for each guest.", "observations": null}, {"name": "Shishito Brasa", "source_page": 31, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "Tumbo Karifawa", "source_page": 32, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "Hongos Teppan", "source_page": 32, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}, {"name": "Yasai Meshi", "source_page": 33, "table_setting": "One sharing spoon in the center of the table and one smaller spoon for each guest.", "observations": null}]$notes$::jsonb) x(name text,source_page integer,table_setting text,observations text);
create temporary table service_notes_targets as select m.id,n.* from service_notes_import n join public.menu_items m on m.name=n.name and m.content_type='food' join public.restaurants r on r.id=m.restaurant_id join auth.users u on u.id=r.owner_id where r.name='Osaka - Miami' and u.email='castem93@gmail.com';
do $$ begin
if (select count(*) from service_notes_targets)<>61 then raise exception 'Expected 61 matching dishes'; end if;
if exists(select 1 from public.menu_items m join service_notes_targets n on n.id=m.id where (m.table_setting is not null and m.table_setting is distinct from n.table_setting) or (m.observations is not null and m.observations is distinct from n.observations)) then raise exception 'Existing service notes differ; review before importing'; end if;
end $$;
update public.menu_items m set table_setting=n.table_setting,observations=n.observations from service_notes_targets n where m.id=n.id and (m.table_setting is distinct from n.table_setting or m.observations is distinct from n.observations);
select count(*) filter(where m.table_setting is not null) as table_settings,count(*) filter(where m.observations is not null) as observations from public.menu_items m join service_notes_targets n on n.id=m.id;
commit;
